for i in range(len(b['admissions'])):s+=' expected:=jsonb_set(expected,'+q('{admissions,'+str(i)+',release_sha256}')+',to_jsonb(root_sha));\n'
s+=' EXECUTE '+q(query)+' INTO actual;\n'+guard("((actual-'captured_at') #- '{root,updated_at}')=(expected #- '{root,updated_at}')",'NATIVE_INTENT_ONLY_METADATA_DIFF')+' EXECUTE '+q(extra)+' INTO after_extra;\n'+guard('after_extra=before_extra','NATIVE_INTENT_SCENE_KEEP')+guard(inflight,'NATIVE_INTENT_ACTIVE_AFTER')+"END $usd_install$;NOTIFY pgrst,'reload schema';COMMIT;\n"
(P/'INSTALL.sql').write_text(s);save('BOUND_MANIFEST.json',{'recipe':ref('RECIPE.json'),'builder':ref('BUILD_INTEGRATED.py'),'review':ref('INTEGRATED_REVIEW.json'),'installer':ref('INSTALL.sql'),'existing_bodies_changed':3,'new_helpers':0,'UI_files_changed':2,'provider_calls':0});print(canon({'installer':ref('INSTALL.sql'),'status':'BOUND_AWAITING_MATERIAL_REVIEW'}))

