CONTRACT.json.source:
{
  "DB": {
    "schema_version": "c1266-native-timeout-db-contract/1",
    "baseline_root": "ea8a7c4fcee14d027b14369f12bdb91dcb496a11c40ee356b0091b53b53d35d3",
    "producer_readonly_rpc": "public.mission_generic_dispatch_async_status_v1(uuid,jsonb)",
    "request_schema": "mission-generic-async-recover/1",
    "request_keys": [
      "schema_version",
      "master_session_id",
      "selector"
    ],
    "new_selector": {
      "exact_keys": [
        "kind",
        "request_key"
      ],
      "kind": "native_tick",
      "request_key": "original mission-generic-tick/1 request_key UUID; never work.request_key"
    },
    "native_tick_scope": "active authenticated Staff participant in active nonsuspended AI-owned manual Staff Test scene with sealed manual source; service-only reader receives p_user from verified Edge auth, never client",
    "lookup": "progress_receipts exact original request_key+master_session_id+actor_user_id and result_sha256=SHA256(result)",
    "progress_validation": "Exact4keys schema/master_session_id/state/dispatch or paused reason MGPG_C7_RUN_BUDGET_STOP exact5; session and state types/hash validated",
    "owned_result": "Only nonnull dispatch passes unchanged canonicalrequest/work/dispatchreceipt/envelope/async-owner/historicalwork checks. DTO existing mission-generic-async-recovery/1 unchanged11keys, actual kind director/narration/choice unchanged. No stafftick successor inference for native_tick.",
    "none_semantics": "Absent receipt, no dispatch, wrong owner/scope or unqualified work returns existing status none, retryfalse/provider_retry_allowedfalse. NONE is uncertainty, NEVER not_sent or proof of absence; it never authorizes new request_key.",
    "UI_recovery": "Persist original generic tick request body/key before original HTTP. After explicit verification first adopt known owned state. Known completed choice confirms originating submission without calling Director->Writer chain. If still uncertain and no conflicting known active work, explicit redelivery ONLY identical original body/key; same producer advisorylock+immutable progressreceipt replay provides idempotence. No auto retry, UUID substitution, PG action resend, journal deletion, budget/time reset or generation retry.",
    "idempotency_source": "mission_generic_progress_v1 service_only->lock_request(originalUUID)->existing receipt/session/user/hash replay before progress_step; current code unchanged. Existing business40001 conflict codes remain a separately documented risk, no predicate relaxed.",
    "performance": {
      "current_principal": "MATERIALIZED cheap sameTX/backend/consumed/150sec/runtime/location eligibility, then distinct actor IDs, actor_principal exactly once/eligible actor/invocation. Same native binding fingerprint, capability, actor_map and ambiguous-principal rejection. No cache across statements/RPC. Same150sec expiry is rechecked after materialized actor hashing, so an expired permit cannot be accepted merely because it passed the cheap prefilter.",
      "journal": "MATERIALIZED complete release candidates with every original row/hash/receipt condition except the unchanged release predicate; distinct requested source IDs only for the two original reasons needing it; unchanged role_source_released_v4 evaluated once/source then materialized released rows. Other saved-application branches and every qualified/published/settled/item CTE byte-identical."
    },
    "unchanged": [
      "Rootpolicy/capUSD1/backing.3136/allcosts/counters/ledger/token",
      "all old Fati/roles/native actions/works/results/raw/receipts",
      "global and perRPC timeouts",
      "all existing ACLs/OIDs/volatility/search_path/securitydefiner",
      "ordinary and legacy request/staff_tick reader branches"
    ],
    "new_objects": 0,
    "existing_bodies_changed": 3,
    "runtime": "NOT_RUN"
  },
  "UI": {
    "schema_version": "c1266-native-timeout-ui-contract/1",
    "producer_consumer": [
      {
        "producer": "progress_v1 normal native tick",
        "consumer": "journal8 before normal invoke",
        "contract": "immutable same original mission-generic-tick/1 session/request_key; readonly native_tick selector session+actor+original progress receipt/hash bound dispatch"
      },
      {
        "producer": "async-recover/1 existing response",
        "consumer": "UI recoveryProof + Edge closed validator",
        "contract": "owned exactcanonicalrequest/work/receipt/kind; native absent or dispatchnull remain none/retryfalse/providerretryfalse. No no_work for native. NONE never closes journal or proves NOT_SENT."
      },
      {
        "producer": "async-status/1 exact canonical status",
        "consumer": "adoptAsyncProof/manual verify",
        "contract": "adopt exact validated work/request/state and completed receipt+SHA; choice/narration do not enter Directorchain; only Director kind allows chain"
      },
      {
        "producer": "journal_settlements existing fresh publication/release",
        "consumer": "settleAsyncRecords and parent attempts",
        "contract": "exactactor/session/work/request receipt reconciles submission; release never fabricates completed work/Fato"
      }
    ],
    "native_replay": "Explicit gesture only, fresh authenticated Room and native_tick reader NONE or exact ownedREADY matching Room work/request/state ready+can_tick, same immutable originalbody/key and original journal8; no other known active work or unrelated observer; claimed/authorized/provider_started/uncertain remain observation-only; normal progress producer locks+receipt check idempotently precede any step. No new UUID, no role resend, no counter/time reset. ACK with dispatchnull closes only submission; owned follows existing work.",
    "journal8": "Exact wrapper schema_version/original:null/recovery; same existing phase fields with closed native_tick selector. Old journal1..7 parsers and persisted content retained. Reload adopts observation only.",
    "server_requirements": [
      "DB async reader native_tick exactsession/user/key with canonical original receipt/hash and dispatch authority",
      "normal progress same-key lock and immutable receipt lookup before any progress step; ownedREADY re-delivery returns exactly that existing dispatch and passes normal idempotent provider gates",
      "Edge accepts ONLY exactnative_tick selector; response no_work remains forbidden for native"
    ],
    "limits": [
      "Source/syntax static evidence only; runtime/reentry/actor isolation to verify in actual Staff",
      "Historical generic ticks without persisted original UUID are not reconstructed or treated as NOT_SENT",
      "No change to provider budget/token/retry authorization or existing Fati/mechanics; explicit ownedREADY same-native-key delivery is approved within normal server gates"
    ]
  },
  "rollout": "Reviewed exact candidate2client/14Edge/3existingDB bodies -> bind actual commit/version -> independent material review -> Root atomic apply -> realStaff same13Fati/acceptedround4 roles only; cap1 unchanged"
}

