{
  "schema_version": "c1266-native-timeout-ui-contract/1",
  "producer_consumer": [
    {
      "producer": "progress_v1 normal native tick",
      "consumer": "journal8 before normal invoke",
      "contract": "immutable same original mission-generic-tick/1 session/request_key; readonly native_tick selector session+actor+original progress receipt/hash bound dispatch"
    },
    {
      "producer": "async-recover/1 existing response",
      "consumer": "UI recoveryProof + Edge closed validator",
      "contract": "owned exactcanonicalrequest/work/receipt/kind; native absent or dispatchnull remain none/retryfalse/providerretryfalse. No no_work for native. NONE never closes journal or proves NOT_SENT."
    },
    {
      "producer": "async-status/1 exact canonical status",
      "consumer": "adoptAsyncProof/manual verify",
      "contract": "adopt exact validated work/request/state and completed receipt+SHA; choice/narration do not enter Directorchain; only Director kind allows chain"
    },
    {
      "producer": "journal_settlements existing fresh publication/release",
      "consumer": "settleAsyncRecords and parent attempts",
      "contract": "exactactor/session/work/request receipt reconciles submission; release never fabricates completed work/Fato"
    }
  ],
  "native_replay": "Explicit gesture only, fresh authenticated Room and native_tick reader NONE or exact ownedREADY matching Room work/request/state ready+can_tick, same immutable originalbody/key and original journal8; no other known active work or unrelated observer; claimed/authorized/provider_started/uncertain remain observation-only; normal progress producer locks+receipt check idempotently precede any step. No new UUID, no role resend, no counter/time reset. ACK with dispatchnull closes only submission; owned follows existing work.",
  "journal8": "Exact wrapper schema_version/original:null/recovery; same existing phase fields with closed native_tick selector. Old journal1..7 parsers and persisted content retained. Reload adopts observation only.",
  "server_requirements": [
    "DB async reader native_tick exactsession/user/key with canonical original receipt/hash and dispatch authority",
    "normal progress same-key lock and immutable receipt lookup before any progress step; ownedREADY re-delivery returns exactly that existing dispatch and passes normal idempotent provider gates",
    "Edge accepts ONLY exactnative_tick selector; response no_work remains forbidden for native"
  ],
  "limits": [
    "Source/syntax static evidence only; runtime/reentry/actor isolation to verify in actual Staff",
    "Historical generic ticks without persisted original UUID are not reconstructed or treated as NOT_SENT",
    "No change to provider budget/token/retry authorization or existing Fati/mechanics; explicit ownedREADY same-native-key delivery is approved within normal server gates"
  ]
}

