def sha(x):return hashlib.sha256(x if isinstance(x,bytes)else x.encode()).hexdigest()
def ref(n):
 p=P/n;return {'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())}
def save(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def q(x):return "'"+(x if isinstance(x,str)else canon(x)).replace("'","''")+"'"
def guard(x,c):return ' IF ('+x+") IS DISTINCT FROM TRUE THEN RAISE EXCEPTION '"+c+"' USING ERRCODE='P0001';END IF;\n"
b=read('DB_BEFORE.json');E=read('EXTRA_BEFORE.json');old=json.loads(b['root']['canonical_preimage']);root=b['root']['revision_sha256'];edge=read('EDGE_BEFORE.json');D=read('SQL_DELTA.json');N=read('NEW_OBJECTS.json');policy=None
assert root=='b7c765a729535a3915b24c11b61d217a17dbb540bce989d39c89efe6f46ae812' and sha(b['root']['canonical_preimage'])==root
assert edge['version']==102 and edge['status']=='ACTIVE' and len(edge['files'])==14 and edge['ezbr_sha256']==old['edge_bundles'][0]['ezbr_sha256']
assert E['active_work_count']==0 and len(E['fati'])==14 and len(E['roles'])==20 and b['protected']['protected_field_count']==48
root_sigs={h['signature']for h in old['db_core']['all_function_headers']};extras={};before={h['signature']:h for h in b['headers']};attrs={};sources={}
for d in D:
 sig=d['signature'];assert before[sig]['source_md5']==d['baseline_prosrc_md5'];assert ref(d['path'])['sha256']==d['candidate_sha256']
 attrs[sig]={**{k:v for k,v in before[sig].items()if k not in ['oid','ddl_md5']},'source_md5':d['candidate_prosrc_md5']};sources[sig]=ref(d['path'])
assert len(D)==1 and len(N['functions'])==0
for f in N['functions']:
 sig=f['signature'];assert sig not in before;attrs[sig]=f['expected_attributes'];sources[sig]=ref(f['path'])
for sig,h in extras.items():
 if sig not in attrs:attrs[sig]={k:v for k,v in h.items()if k not in ['oid','ddl_md5']};sources[sig]=ref('baseline/'+sig.split('(')[0].replace('.','__')+'.sql')
expected_edge=read('EXPECTED_EDGE.json')['files'];expected_ui=read('EXPECTED_UI.json');assert len(b['headers'])==175
recipe={'schema_version':'mission-native-timeout-recovery-recipe/1','baseline_root':root,'builder':ref('BUILD_INTEGRATED.py'),'postflight_checker':ref('POSTFLIGHT_CHECK.py'),'baseline_query':ref('BASELINE.sql'),'extra_query':ref('EXTRA.sql'),'baseline_db':ref('DB_BEFORE.json'),'baseline_scene':ref('EXTRA_BEFORE.json'),'baseline_edge':ref('EDGE_BEFORE.json'),'author':ref('AUTHOR.json'),'static':ref('AUTHOR_STATIC.json'),'contract':ref('CONTRACT.json'),'new_objects':ref('NEW_OBJECTS.json'),'sources':sources,'expected_attributes':attrs,'matrix':ref('MATRIX.json'),'source_packet':ref('SOURCE_REVIEW_PACKET.json'),'dependency_refs':{f.name:ref('dependencies/'+f.name) for f in (P/'dependencies').iterdir()},'expected_edge_files':expected_edge,'expected_UI':expected_ui,'expected_Edge':read('EXPECTED_EDGE.json'),'existing_bodies_changed':1,'new_helpers':0,'new_tables':0,'provider_calls':0,'active_work_condition':'zero ready/claimed/authorized/provider_started/uncertain; no provider in flight','operation':'Project completed native choices only through their exact consumed command, native receipt and published round/report/Writer proof. Collective publication settles an observer without ownership or retry authority. Preserve sealed scene, admission, counters, economics and14publishedFati.','rollout':'integrated source review -> unchanged actual Edge102/client4 then actual bound readbacks -> bind -> materialreview -> fresh baseline zeroactive -> atomicDBRoot -> normalStaffgesture','runtime':'NOT_RUN','history':'same request cumulative deroga5 retained, no reset'}
mode=sys.argv[1]if len(sys.argv)>1 else 'prepare'
if mode=='prepare':save('RECIPE.json',recipe);print(canon({'recipe':ref('RECIPE.json'),'status':'PREPARED_NOT_INSTALLABLE'}));raise SystemExit
assert recipe==read('RECIPE.json'),'recipe drift';review=read('INTEGRATED_REVIEW.json');assert review['findings_count']=={'P0':0,'P1':0,'P2':0}
assert ref('RECIPE.json')['sha256']in canon(review) and ref('BUILD_INTEGRATED.py')['sha256']in canon(review)
after=read('EDGE_AFTER.json');assert after['status']=='ACTIVE' and after['version']==102 and len(after['files'])==14
observed_files=[{'name':f['name'],'bytes':len(f['content'].encode()),'sha256':sha(f['content'].encode())}if 'content'in f else {k:f[k]for k in ['name','bytes','sha256']}for f in after['files']]
assert sorted(observed_files,key=lambda x:x['name'])==sorted(expected_edge,key=lambda x:x['name'])
new=copy.deepcopy(old)
new['edge_bundles']=[read('EDGE_ROOT_BOUND.json')];new['ui']=read('UI_BOUND.json');assert new['ui']['files']==expected_ui['files'] and new['ui']['verified'] is True
new['db_core']['sha256']=sha(canon({'previous':old['db_core']['sha256'],'sources':sources,'attrs':attrs}));new['config']['c1266_choice_publication_settlement_proof']={'schema_version':'mission-native-timeout-recovery-proof/1','source_review':ref('INTEGRATED_REVIEW.json'),'recipe':ref('RECIPE.json'),'previous_release_sha256':root,'provider_calls':0}
cfg=copy.deepcopy(new['config']);cfg.pop('sha256',None)
for k in ['c1266_clean_staff','c1266_staff_campaign']:
 for field in ['grant_id','not_before','expires_at']:cfg[k].pop(field,None)
cfg['c1266_opening'].pop('admission_not_before',None);new['config']['sha256']=sha(canon(cfg));new['contract']['code_identity_sha256']=sha(canon({'db':new['db_core']['sha256'],'edge':new['edge_bundles'],'UI':new['ui'],'config':new['config']['sha256']}))
assert new['recovery']==old['recovery'];assert {k:v for k,v in new['config'].items() if k not in ['sha256','c1266_choice_publication_settlement_proof']}=={k:v for k,v in old['config'].items()if k!='sha256'}
save('EXPECTED_ROOT.json',new)
query=(P/'BASELINE.sql').read_text().strip().rstrip(';');extra=(P/'EXTRA.sql').read_text().strip().rstrip(';');expected={k:v for k,v in b.items()if k!='captured_at'}
inflight="NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE status IN('reserved','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND state IN('ready','claimed','authorized','provider_started','uncertain'))"
s="""-- One existing projection body plus backward-compatible Edge/native reader/UI composition. No table/player/history mutation, provider call or budget increase.
BEGIN;SET LOCAL search_path TO pg_catalog,public,extensions;SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $usd_install$
DECLARE heads jsonb;actual jsonb;expected jsonb;newpre jsonb;before_extra jsonb;after_extra jsonb;root_text text;root_sha text;n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;
 PERFORM public.master_v2_lock_scope('44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid);
"""
for t in ['mission_factory_owner.editor_release_readiness','mission_factory_owner.c464_control','mission_factory_owner.provider_authoring_runtime','mission_generic_owner.runtime_policy','mission_generic_owner.provider_policy','mission_generic_owner.flow_runtime_gate']:s+=' PERFORM 1 FROM '+t+' WHERE singleton FOR UPDATE;\n'
s+=" PERFORM 1 FROM mission_generic_owner.dispatch_admissions WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;\n PERFORM 1 FROM mission_factory_owner.provider_authoring_admissions ORDER BY actor_user FOR UPDATE;\n"+guard(inflight,'NATIVE_INTENT_ACTIVE_WORK')
s+=' EXECUTE '+q(query)+' INTO actual;expected:='+q(expected)+'::jsonb;\n'+guard("(actual-'captured_at')=expected",'NATIVE_INTENT_BASELINE_DRIFT')+' EXECUTE '+q(extra)+' INTO before_extra;\n'+guard('before_extra='+q(E)+'::jsonb','NATIVE_INTENT_SCENE_DRIFT')
for f in N['functions']:s+=guard('to_regprocedure('+q(f['signature'])+') IS NULL','NATIVE_INTENT_NEW_HELPER_ABSENT')+' EXECUTE '+q((P/f['path']).read_text())+';\n'
for d in D:s+=' EXECUTE '+q((P/d['path']).read_text())+';\n'
s+=' newpre:='+q(new)+'::jsonb;\n'
for sig,a in attrs.items():
 headquery="SELECT jsonb_build_object('signature',"+q(sig)+",'oid',p.oid::bigint,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'volatility',p.provolatile::text,'language',l.lanname,'source_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure("+q(sig)+")"
 s+=' EXECUTE '+q(headquery)+' INTO heads;\n'+guard("(heads-'oid'-'ddl_md5')="+q(a)+'::jsonb','NATIVE_INTENT_ATTRS')
 if sig in before:s+=guard("heads->>'oid'="+q(str(before[sig]['oid'])),'NATIVE_INTENT_EXISTING_OID')
 for key in ['pins','target_bodies','c1266_functions','all_function_headers','additional_dependencies','context24_functions']:
  path='{db_core,'+key+'}'
  s+=' newpre:=jsonb_set(newpre,'+q(path)+",(SELECT jsonb_agg(CASE WHEN h->>'signature' IN("+q(sig)+','+q(sig.split('.',1)[1])+") THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>"+q(path)+") WITH ORDINALITY rows(h,ord)));\n"
 if sig not in root_sigs:
  for key in ['c1266_functions','all_function_headers']:s+=' newpre:=jsonb_set(newpre,'+q('{db_core,'+key+'}')+',(newpre#>'+q('{db_core,'+key+'}')+")||jsonb_build_array(heads));\n"
 s+=" expected:=jsonb_set(expected,'{headers}',(SELECT jsonb_agg(x ORDER BY x->>'signature') FROM (SELECT CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END x FROM jsonb_array_elements(expected->'headers') h"+(" UNION ALL SELECT heads"if sig not in before else '')+" ) z));\n"
 if sig in extras:s+=" expected:=jsonb_set(expected,'{legal_dependencies}',(SELECT jsonb_agg(CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END ORDER BY h->>'signature') FROM jsonb_array_elements(expected->'legal_dependencies') h));\n"
s+=" root_text:=newpre::text;\n"+guard('octet_length(root_text)<=262144','NATIVE_INTENT_ROOT_SIZE')+" root_sha:=encode(extensions.digest(convert_to(root_text,'UTF8'),'sha256'),'hex');\n"
s+=" UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=root_text,revision_sha256=root_sha,observed_revision_sha256=root_sha,client_build='mission-factory-admin/2:'||root_sha,updated_at=clock_timestamp() WHERE singleton AND revision_sha256="+q(root)+';\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','NATIVE_INTENT_ROOT_CAS')
s+=' UPDATE mission_factory_owner.c464_control SET release_sha256=root_sha WHERE singleton;\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','NATIVE_INTENT_G2_CAS')
s+=' UPDATE mission_factory_owner.provider_authoring_admissions SET release_sha256=root_sha WHERE actor_user IN('+','.join(q(a['actor_user'])for a in b['admissions'])+');\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n='+str(len(b['admissions'])),'NATIVE_INTENT_ADMISSIONS_CAS')
for path,expr in [('{root,canonical_preimage}','to_jsonb(root_text)'),('{root,revision_sha256}','to_jsonb(root_sha)'),('{root,observed_revision_sha256}','to_jsonb(root_sha)'),('{root,client_build}',"to_jsonb('mission-factory-admin/2:'||root_sha)"),('{g2,release_sha256}','to_jsonb(root_sha)')]:s+=' expected:=jsonb_set(expected,'+q(path)+','+expr+');\n'
for i in range(len(b['admissions'])):s+=' expected:=jsonb_set(expected,'+q('{admissions,'+str(i)+',release_sha256}')+',to_jsonb(root_sha));\n'
s+=' EXECUTE '+q(query)+' INTO actual;\n'+guard("((actual-'captured_at') #- '{root,updated_at}')=(expected #- '{root,updated_at}')",'NATIVE_INTENT_ONLY_METADATA_DIFF')+' EXECUTE '+q(extra)+' INTO after_extra;\n'+guard('after_extra=before_extra','NATIVE_INTENT_SCENE_KEEP')+guard(inflight,'NATIVE_INTENT_ACTIVE_AFTER')+"END $usd_install$;NOTIFY pgrst,'reload schema';COMMIT;\n"
(P/'INSTALL.sql').write_text(s);save('BOUND_MANIFEST.json',{'recipe':ref('RECIPE.json'),'builder':ref('BUILD_INTEGRATED.py'),'review':ref('INTEGRATED_REVIEW.json'),'installer':ref('INSTALL.sql'),'existing_bodies_changed':1,'new_helpers':0,'UI_files_changed':2,'provider_calls':0});print(canon({'installer':ref('INSTALL.sql'),'status':'BOUND_AWAITING_MATERIAL_REVIEW'}))

