MATRIX.json.source:
{
  "status": "STATIC_CONTRACT_CASES_ONLY",
  "cases": [
    {
      "case": "click while roomread ongoing",
      "condition": "syncenqueue beforefirstawait; block newautopolls",
      "expected": "local100mswait<=10s thenfreshnormalread"
    },
    {
      "case": "auto observer busy",
      "condition": "let currentread complete, stopnewobserver/driverstarts",
      "expected": "boundedlocalwait, no serverpoll added"
    },
    {
      "case": "repeatedclick whilequeued",
      "condition": "singlelane samePromise and busycontrols",
      "expected": "no duplicateprovider/UUID"
    },
    {
      "case": "timeout",
      "condition": "currentreadnotfinished10s",
      "expected": "visible no-send-this-command notice; lane released; old requestunknownunchanged"
    },
    {
      "case": "fresh same-room response changes session",
      "condition": "post-await manualLaneCurrent checks captured actor/host/epoch/session before scans, adoption and handoff",
      "expected": "cancel oldgesture; no replay, settlement or resume in replacement scene"
    },
    {
      "case": "manualverify",
      "condition": "laneownreadonlyfreshread and existing boundedmanualprooflogic",
      "expected": "no implicit progress/providerretry"
    },
    {
      "case": "native replay",
      "condition": "laneownfreshread and all existingproof/UUID/journalguards",
      "expected": "onlysameoriginalcommand afterrevalidation"
    },
    {
      "case": "manualrefresh",
      "condition": "samequeue and freshnormalroomread",
      "expected": "existingdriver allowed onlyusing ownprivate token, all existingservergates"
    },
    {
      "case": "inflightprovider",
      "condition": "no abort/controller cancellation",
      "expected": "runningprovider lifecycle continues; no newautomaticobserverstarts whilewaiting"
    },
    {
      "case": "legacyverify_resume",
      "condition": "same lane propagated through existingnoWorkreplay",
      "expected": "oldidentity/counters/authoritychecksunchanged"
    },
    {
      "case": "renderexception",
      "condition": "try/finally ownsbusy release",
      "expected": "genericvisibleerror, no stucklane/no unhandledrenderPromise"
    }
  ],
  "no_gameplay_execution": true
}

